{
  "symbol": "{{symbol}}",
  "candleCount": 4,
  "resultType": "float",
  "script": "package main
import "indicator"
func Calculate(data []indicator.KCandle) map[string]float64 {
	sum := 0.0
	for _, candle := range data {
		sum += candle.Close
	}
	return map[string]float64{"movingAverage": sum / float64(len(data))}
}"
}

{
  "symbol": "{{symbol}}",
  "candleCount": 4,
  "script": "package main
import "indicator"
func Calculate(data []indicator.KCandle) map[string]float64 {
	highest := data[0].High
	lowest := data[0].Low
	for _, candle := range data {
		if candle.High > highest {
			highest = candle.High
		}
		if candle.Low < lowest {
			lowest = candle.Low
		}
	}
	return map[string]float64{"highest": highest, "lowest": lowest}
}"
}

